patchSnippet.securePatched:
// Strict tenant isolation enforcement
app.get('/api/v1/tenant/:tenantId/telemetry', async (req, res) => {
  if (req.user.tenantId !== req.params.tenantId) {
    return res.status(403).json({ error: 'Access Denied: Tenant Boundary Violation' });
  }
  const logs = await db.telemetry.find({ tenantId: req.user.tenantId });
  res.json(logs);
});
